const P = {"tool": "Human-AI Teaming Interface", "tasks": [{"id": "sense", "dur": 4, "deps": []}, {"id": "plan", "dur": 3, "deps": ["sense"]}, {"id": "act", "dur": 2, "deps": ["plan"]}, {"id": "verify", "dur": 2, "deps": ["act"]}]};

function demoMain(P){
  var tasks=P.tasks, order=[], done={}, guard=0, ti;
  while(order.length<tasks.length && guard++<1000){
    for(ti=0; ti<tasks.length; ti++){ var t=tasks[ti]; if(done[t.id]) continue;
      var ready=true, di; for(di=0; di<t.deps.length; di++) if(!done[t.deps[di]]) ready=false;
      if(ready){ done[t.id]=1; order.push(t.id); } }
  }
  var fin={}, cp=0, oi;
  for(oi=0; oi<order.length; oi++){ var tt=null, tj; for(tj=0;tj<tasks.length;tj++) if(tasks[tj].id===order[oi]) tt=tasks[tj];
    var st=0, dk; for(dk=0; dk<tt.deps.length; dk++) st=Math.max(st, fin[tt.deps[dk]]||0);
    fin[tt.id]=st+tt.dur; cp=Math.max(cp, fin[tt.id]); }
  return 'Task decomposition ('+P.tool+'): order='+order.join('>')+' critical-path='+cp+' time-units, all dependencies satisfied';
}
console.log(demoMain(P));

